B.Qd=new A.c3("ListView.builder(\n  itemCount: items.length,\n  itemBuilder: (context, index) {\n    return CourseTile(item: items[index]);\n  },\n)\n\nconst SizedBox(height: 12);",B.Vx,B.SV,B.Zq,B.Us)
B.Vt=s(["Semantics aporta informaci\xf3n adicional cuando la apariencia visual no comunica suficiente contexto.","Tooltip ayuda a identificar acciones representadas \xfanicamente por iconos.","El contraste, tama\xf1o t\xe1ctil y orden de foco forman parte de la usabilidad, no son extras.","Una app debe poder recorrerse con teclado en escritorio y web."],t.s)
B.Rl=new A.aS("Bot\xf3n con intenci\xf3n clara","Tooltip y Semantics describen la misma acci\xf3n para diferentes formas de interacci\xf3n.","Semantics(\n  label: 'Eliminar libro de favoritos',\n  button: true,\n  child: IconButton(\n    tooltip: 'Quitar de favoritos',\n    onPressed: onRemove,\n    icon: const Icon(Icons.star),\n  ),\n)","")
B.S_=new A.aS("Campo comprensible","Un label persistente es m\xe1s claro que depender \xfanicamente de un hint temporal.","TextFormField(\n  decoration: const InputDecoration(\n    labelText: 'Correo electr\xf3nico',\n    hintText: 'nombre@ejemplo.com',\n  ),\n  keyboardType: TextInputType.emailAddress,\n  autofillHints: const [AutofillHints.email],\n)","")
